  setMemoryStatus('Fetching memory preview...');
  const body = {
    query,
    query_source: source,
    project: memory.project || 'global',
    scope: 'global',
    max_tokens: memory.maxTokens,
    top_k: memory.topK,
    min_score: memory.minScore,
