    exclude_classes: memory.excludeClasses || [],
    return_format: 'json',
  };
  const res = await chrome.runtime.sendMessage({ type: 'PREVIEW_MEMORY_PACK', body });
  if (!res?.ok) {
    setMemoryStatus(`Preview failed: ${res?.error || 'unknown error'}`);
